46	type TemplateMatchable interface {
47		GetRegistryName() string
48		GetTemplateName() string
49		GetSource() string
50		GetPublisher() string
51	}
52	
53	func NewTemplateMatcher(templateName string) (func(TemplateMatchable) bool, error) {
54		if templateName == "" {
55			return func(TemplateMatchable) bool { return true }, nil
56		}
57	
58		var urlInfo *registry.URLInfo
59		var err error
60	
61		// 1. Try parsing as a strict registry:// URL
62		if registry.IsRegistryURL(templateName) {
63			urlInfo, err = registry.ParseRegistryURL(templateName)
64			if err != nil {
65				var invalidRegistryURL *registry.InvalidRegistryURLError
66				if errors.As(err, &invalidRegistryURL) {
67					// Wrap this particular error reason because formats other than the
68					// full registry:// URL format are supported by `pulumi new`.
69					if strings.Contains(invalidRegistryURL.Reason, "expected format") {
70						return nil, errors.New("Expected: registry://templates/source/publisher/name[@version], " +
71							"source/publisher/name[@version], publisher/name[@version], or name[@version]")
72					}
73				}
74				return nil, err
75			}
76			if urlInfo.ResourceType() != "templates" {
77				return nil, fmt.Errorf("resource type '%s' is not valid for templates", urlInfo.ResourceType())
78			}
79		} else {
80			// 2. Try parsing as a partial registry URL
81			urlInfo, err = registry.ParsePartialRegistryURL(templateName, "templates")
82			if err != nil {
83				var missingVersion *registry.MissingVersionAfterAtSignError
84				if errors.As(err, &missingVersion) {
85					return nil, err
86				}
87	
88				// Structural errors: fall back to name matching
89				urlInfo = nil
90			}
91		}
92	
93		// Validation: versions other than "latest" are not yet supported because the
94		// list endpoint used by `pulumi new` only returns the latest version.
95		if urlInfo != nil && urlInfo.Version() != nil {
96			return nil, &registry.UnsupportedVersionError{Version: urlInfo.Version().String()}
97		}
98	
99		return matcherFromURLInfo(urlInfo, templateName), nil
100	}
101	
102	func matcherFromURLInfo(urlInfo *registry.URLInfo, templateName string) func(TemplateMatchable) bool {
103		if urlInfo == nil {
104			return func(t TemplateMatchable) bool {
105				return t.GetRegistryName() == templateName || t.GetTemplateName() == templateName
106			}
107		}
108	
109		return func(t TemplateMatchable) bool {
110			if urlInfo.Source() != "" && t.GetSource() != urlInfo.Source() {
111				return false
112			}
113			if urlInfo.Publisher() != "" && t.GetPublisher() != urlInfo.Publisher() {
114				return false
115			}
116			if urlInfo.Name() != "" {
117				return t.GetRegistryName() == urlInfo.Name() || t.GetTemplateName() == urlInfo.Name()
118			}
119			return true
120		}
121	}
